import argparse
import json

from .detect import init_sensor_cache, set_detect_enabled
from . import listConnectedDevIDs


def main() -> None:
    ap = argparse.ArgumentParser(
        prog="dmrobotics",
        description=(
            "Daimon tactile sensor command line tools.\n"
            "Use this CLI to inspect connected sensors and manage detect-based inspection."
        ),
        epilog=(
            "Examples:\n"
            "  dmrobotics list\n"
            "  dmrobotics init M2505150298\n"
            "  dmrobotics set_detect True"
        ),
        formatter_class=argparse.RawTextHelpFormatter,
    )
    sub = ap.add_subparsers(
        dest="cmd",
        required=True,
        title="commands",
        metavar="{list,set_detect,init}",
    )

    sub.add_parser(
        "list",
        help="List all currently connected compliant tactile sensors.",
        description="Query Flux camera discovery and print the detected devices.",
    )

    init_parser = sub.add_parser(
        "init",
        help="Capture and cache a detect reference image for one sensor.",
        description=(
            "Capture one reference image from the specified sensor camera and save it\n"
            "to the detect cache for later inspection."
        ),
        formatter_class=argparse.RawTextHelpFormatter,
    )
    init_parser.add_argument("serial", help="Sensor serial or unique serial suffix.")
    init_parser.add_argument(
        "--timeout-ms",
        type=int,
        default=3000,
        help="Timeout for grabbing a frame from the camera.",
    )

    set_detect = sub.add_parser(
        "set_detect",
        help="Globally enable or disable detect inspection.",
        description=(
            "Turn detect-based inspection on or off.\n"
            "When disabled, detect comparison returns True without checking the image."
        ),
        formatter_class=argparse.RawTextHelpFormatter,
    )
    set_detect.add_argument(
        "enabled",
        help="Set to True to enable detection, or False to disable it.",
    )

    args = ap.parse_args()

    if args.cmd == "list":
        devices = listConnectedDevIDs()
        print(json.dumps(devices, ensure_ascii=False, indent=2))
        return

    if args.cmd == "set_detect":
        _ok, message = set_detect_enabled(args.enabled)
        print(message)
        return

    if args.cmd == "init":
        success, message = init_sensor_cache(serial=args.serial, timeout_ms=args.timeout_ms)
        print(message)
        print(str(success))
        return

    raise ValueError(f"unsupported command: {args.cmd}")


if __name__ == "__main__":
    main()
